from pathlib import Path
import json,gzip,hashlib,re,ast,types
root=Path('/home/osso/.worktrees/wow-ui-sim-p333-source'); here=root/'data/patch-api/evidence/3.3.3-session-2026-10-09'
sha=lambda b:hashlib.sha256(b).hexdigest()
manifest=json.loads((here/'historical-inputs.json').read_bytes()); blobs=json.loads(gzip.decompress((here/'historical-blobs.json.gz').read_bytes()))
sealed={}
for p,v in manifest['sealed_files'].items():
 b=(here/p).read_bytes(); assert sha(b)==v['sha256'] and len(b)==v['bytes'],p
 sealed[p]={'sha256':sha(b),'bytes':len(b)}
assert len(sealed)==22 and len(blobs)==76
b=(here/'historical-blobs.json.gz').read_bytes(); assert sha(b)==manifest['archive_sha256'] and len(b)==manifest['archive_bytes']==292043
archived={}
for p,text in blobs.items():
 assert sha(text.encode())==manifest['archived_paths'][p],p
 archived[p]={'sha256':sha(text.encode()),'bytes':len(text.encode()),'current_equal':(root/p).exists() and (root/p).read_bytes()==text.encode()}
current_files={}
for p in (root/'data/patch-api/sources').glob('3.3.3*'):
 current_files[str(p.relative_to(root))]={'sha256':sha(p.read_bytes()),'bytes':len(p.read_bytes())}
for live,frozen in [('3.3.3-api-changes.wikitext','historical-source.wikitext'),('3.3.3-api-changes.txt','historical-extract.txt'),('3.3.3-api-changes.provenance.json','historical-provenance.json'),('3.3.3-wikitext-register.json','historical-register.json'),('3.3.3-page-coverage.json','historical-page-coverage.json'),('3.3.3-signatures.json','historical-signatures.json')]:
 assert (root/'data/patch-api/sources'/live).read_bytes()==(here/frozen).read_bytes(),live
assert (root/'tests/data/patch_3_3_3_sweep_known_gaps.json').read_bytes()==(here/'historical-known-gaps.json').read_bytes()
own=json.loads((here/'historical-register.json').read_bytes()); assert own['client_line']=='retail' and len(own['entries'])==36
sweep=(root/'tests/patch_3_3_3_publication_sweep.rs').read_text()
paths=re.findall(r'include_str!\("\.\./(data/patch-api/sources/[^\"]+-wikitext-register.json)"\)',sweep)[1:]
assert paths==['data/patch-api/sources/3.3.5-wikitext-register.json','data/patch-api/sources/4.0.1-wikitext-register.json']+manifest['later_registers']
actual=[]
for p in paths:
 b=(root/p).read_bytes(); register=json.loads(b)
 assert register.get('client_line','retail')=='retail',p
 if p in manifest['later_registers']:assert b==blobs[p].encode(),p
 actual.append({'path':p,'patch':register['patch'],'client_line':register.get('client_line','retail'),'entries':len(register['entries']),'sha256':sha(b)})
keys=lambda register:{(e['section'],e['symbol']) for e in register['entries']}
symbols=lambda register:{e['symbol'] for e in register['entries']}
added=[]
for p in paths[:2]:
 register=json.loads((root/p).read_bytes()); pairs=keys(own)&keys(register); names=symbols(own)&symbols(register)
 assert not pairs and not names,p
 added.append({'path':p,'rows':len(register['entries']),'section_symbol_overlap':sorted(pairs),'bare_symbol_overlap':sorted(names)})
def expected(later):
 latest={}
 for register in later:
  for e in register['entries']:
   if e['direction']!='changed':latest[e['symbol']]=e
 result={}
 for e in own['entries']:
  newer=latest.get(e['symbol']); own_removed=e['direction']=='removed'
  removed=newer['direction']=='removed' if newer else own_removed
  result[e['id']]={'direction':e['direction'],'page_default':e.get('page_default'),'symbol':e['symbol'],'section':e['section'],'publication':'absent' if removed else 'published','superseded_by':newer['id'] if newer and removed!=own_removed else None}
 return result
historical=expected([json.loads(blobs[p]) for p in manifest['later_registers']]); current=expected([json.loads((root/p).read_bytes()) for p in paths]); assert historical==current
original=json.loads((here/'own-sweep-green-results.json').read_bytes()); assert all(original[k]['expected']==v for k,v in historical.items()); assert sum(v['ok'] for v in original.values())==25 and sum(not v['ok'] for v in original.values())==11
proof=json.loads((here/'validator-development-proof.json').read_bytes())
for p,v in proof['input_seals'].items():
 b=(here/p).read_bytes(); assert sha(b)==v['sha256'] and len(b)==v['bytes'],p
assert sha((root/'tools/test_patch_3_3_3_validator.py').read_bytes())==proof['test_sha256']
# Confirm current/archived heading parser body identical; execute real default extraction, not test suite.
tool='tools/gen_patch_wikitext_register.py'
def function(code,name):return next(n for n in ast.parse(code).body if isinstance(n,ast.FunctionDef) and n.name==name)
assert ast.dump(function(blobs[tool],'parse_historical_api_headings'))==ast.dump(function((root/tool).read_text(),'parse_historical_api_headings'))
extractor=types.ModuleType('current_extractor'); extractor.__file__=str(root/'tools/extract_patch_non_inventory.py'); exec(compile((root/'tools/extract_patch_non_inventory.py').read_text(),'tools/extract_patch_non_inventory.py','exec'),extractor.__dict__)
text=extractor.extract_text((here/'historical-source.wikitext').read_text()); assert text==(here/'historical-extract.txt').read_text()
logs=[]
for command in json.loads((here/'command-ledger.json').read_bytes())['commands']:
 b=(here/command['artifact']).read_bytes();logs.append({'command':command,'log':b.decode(),'sha256':sha(b),'bytes':len(b)})
result={'sealed_files':sealed,'archive_files':archived,'archive_bytes':292043,'archive_sha256':manifest['archive_sha256'],'manifest_sha256':sha((here/'historical-inputs.json').read_bytes()),'current_own_files':current_files,'original_and_current_own_source_accounting_equal':True,'actual_successors':actual,'added_successors':added,'original_successors':68,'current_successors':len(actual),'all_36_complete_expectations_unchanged':True,'original_publication_ok':25,'original_publication_gaps':11,'heading_parser_ast_unchanged':True,'current_default_extract_equals_original':True,'historical_logs':logs,'validator_development_proof':proof,'validator_green_log':(here/'validator-green.txt').read_text()}
print(json.dumps(result,indent=2,sort_keys=True))

